use std::cmp::Ordering;

/// Compares two binary numbers represented as vectors of '0'/'1' chars.
/// 
/// Returns:
/// - `-1` if `s1` is numerically less than `s2`
/// - `0`  if `s1` equals `s2`
/// - `1`  if `s1` is numerically greater than `s2`
/// 
/// Both `s1` and `s2` are assumed to be non-empty, canonical binary representations:
/// either `['0']` for zero or starting with `'1'` when representing a positive number.
fn compare(s1: Vec<char>, s2: Vec<char>) -> i32 {
    match s1.iter().cmp(s2.iter()) {
        Ordering::Less    => -1,
        Ordering::Equal   => 0,
        Ordering::Greater => 1,
    }
}

